examples.template:
MonarchButton(
    text = {{trigger}},
    onClick = {
        step = "review"
        understood = false
        typed = ""
        open = true
    },
    variant = MonarchButtonVariant.Danger,
)
if (open && step != "verify") {
    // While the work runs, back or a tap outside does not close the dialog.
    MonarchDialog(
        onDismissRequest = { open = false },
        title = if (step == "done") "Personal data erased" else "Erase personal data",
        dismissible = !erasing,
        actions = when (step) {
            "review" -> {
                {
                    MonarchButton(text = "Cancel", onClick = { open = false }, size = MonarchButtonSize.Sm)
                    MonarchButton(
                        text = "Continue",
                        onClick = { step = "confirm" },
                        variant = MonarchButtonVariant.Danger,
                        size = MonarchButtonSize.Sm,
                    )
                }
            }
            "confirm" -> {
                {
                    MonarchButton(text = "Back", onClick = { step = "review" }, size = MonarchButtonSize.Sm)
                    MonarchButton(
                        text = "Erase data",
                        onClick = { step = "verify" },
                        variant = MonarchButtonVariant.Danger,
                        size = MonarchButtonSize.Sm,
                        enabled = understood && MonarchTypeToConfirmInputDefaults.matches(typed, subject),
                    )
                }
            }
            else -> {
                {
                    MonarchButton(
                        text = "Done",
                        onClick = { open = false },
                        variant = MonarchButtonVariant.Primary,
                        size = MonarchButtonSize.Sm,
                    )
                }
            }
        },
    ) {
        Column(
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
        ) {
            when (step) {
                "review" -> {
                    MonarchText(text = "Step 1 of 2", style = MonarchTextStyle.Caption)
                    MonarchProgress(progress = 0.5f, size = MonarchProgressSize.Sm)
                    MonarchText(text = "What happens", style = MonarchTextStyle.Subheading, heading = true)
                    MonarchText(
                        text = "This erases the personal data held about " + {{subjectName}} + ".",
                        style = MonarchTextStyle.Caption,
                    )
                    MonarchConsequenceList(
                        items = listOf(
                            MonarchConsequence(MonarchConsequenceKind.Removed, {{erased.0.label}}),
                            MonarchConsequence(MonarchConsequenceKind.Removed, {{erased.1.label}}, count = {{erased.1.count}}),
                            MonarchConsequence(MonarchConsequenceKind.Removed, {{erased.2.label}}, count = {{erased.2.count}}),
                            MonarchConsequence(MonarchConsequenceKind.Removed, {{erased.3.label}}),
                        ),
                        heading = "Will be erased",
                    )
                    MonarchConsequenceList(
                        items = listOf(
                            MonarchConsequence(MonarchConsequenceKind.Kept, {{retained.0.label}}, detail = {{retained.0.reason}}),
                            MonarchConsequence(MonarchConsequenceKind.Kept, {{retained.1.label}}, detail = {{retained.1.detail}}),
                        ),
                        heading = "Will be kept",
                    )
                    MonarchInlineNotice(
                        message = "Erased data cannot be recovered, by you or by support.",
                        tone = MonarchTone.Danger,
                        title = "This cannot be undone",
                    )
                }
                "confirm" -> {
                    MonarchText(text = "Step 2 of 2", style = MonarchTextStyle.Caption)
                    MonarchProgress(progress = 1f, size = MonarchProgressSize.Sm)
                    MonarchText(text = "Confirm the erasure", style = MonarchTextStyle.Subheading, heading = true)
                    MonarchText(
                        text = "Erase the personal data of " + {{subjectName}} + " now.",
                        style = MonarchTextStyle.Caption,
                    )
                    MonarchCheckboxRow(
                        checked = understood,
                        onCheckedChange = { understood = it },
                        label = "I understand this cannot be undone",
                    )
                    MonarchTypeToConfirmInput(
                        phrase = subject,
                        value = typed,
                        onValueChange = { typed = it },
                        label = "Type $subject to confirm",
                    )
                }
                else -> {
                    MonarchText(text = "The personal data of " + {{subjectName}} + " has been erased.")
                    auditId?.let { MonarchText(text = "Logged in the audit log. Reference: $it") }
                }
            }
        }
    }
}
if (open && step == "verify") {
    MonarchDialog(onDismissRequest = { step = "confirm" }, title = null, dismissible = !erasing) {
        MonarchStepUpAuthDialog(
            onVerify = { _ ->
                // Send the credential to the server; throw if it is refused.
            },
            description = "Erasing personal data needs you to confirm your identity.",
            onCancel = { step = "confirm" },
            onVerified = {
                erasing = true
                scope.launch {
                    // Erase on the server, which returns the audit log entry.
                    auditId = {{auditId}}
                    erasing = false
                    step = "done"
                }
            },
            onVerifyingChange = { erasing = it },
        )
    }
}

